// Polling data, grouped by race. Senate 2026 only for now; the shape is
// deliberately generic (raceType + optional district/seatClass) so House,
// governor, and presidential races can be added later without a schema change.
//
// SOURCE: RealClearPolling (realclearpolling.com). This file is meant to be
// regenerated by `pnpm polls:pull` (see scripts/pull-polls.mjs) -- do not
// hand-maintain it long-term. The entries below are a hand-seeded EXAMPLE for
// Ohio so the page has something to render; numbers need replacing with a real
// pull.

export type RaceType = "senate" | "house" | "governor" | "president";
export type PartyCode = "D" | "R" | "I" | "O";
export type PollPopulation = "LV" | "RV" | "A"; // likely / registered voters, adults

export interface PollResult {
  candidate: string;
  party: PartyCode;
  pct: number;
}

export interface Poll {
  pollster: string;
  /** ISO dates for the field period. */
  startDate: string;
  endDate: string;
  sampleSize?: number;
  population?: PollPopulation;
  /** Link to the poll or its RCP entry. */
  url?: string;
  results: PollResult[];
}

export interface RacePolls {
  raceType: RaceType;
  /** USPS state code. */
  state: string;
  /** House only. */
  district?: number;
  /** Senate only. */
  seatClass?: 1 | 2 | 3;
  special?: boolean;
  /** Display title, e.g. "Ohio Senate (special)". */
  title: string;
  candidates: { name: string; party: PartyCode; incumbent?: boolean }[];
  polls: Poll[];
  /** The aggregator's own headline average, if the source publishes one. */
  aggregateAverage?: {
    spread: string;
    period: string;
    results: PollResult[];
  };
  /** Where the polls came from and when they were last refreshed. */
  source: string;
  lastPulled?: string;
}

import generated from "~/data/polls.generated.json";

/** A stable key for a race, so a real pull can replace the seeded example. */
function raceKey(r: Pick<RacePolls, "raceType" | "state" | "district">): string {
  return `${r.raceType}:${r.state}:${r.district ?? ""}`;
}

/** Hand-seeded races. Normally empty -- `pnpm polls:pull` fills
 *  polls.generated.json, whose races override these by key. */
const SEEDED: RacePolls[] = [];

const GENERATED = (generated.races ?? []) as unknown as RacePolls[];

/** All races: a pulled race replaces the seeded example with the same key. */
export const POLLS: RacePolls[] = (() => {
  const byKey = new Map<string, RacePolls>();
  for (const race of SEEDED) byKey.set(raceKey(race), race);
  for (const race of GENERATED) byKey.set(raceKey(race), race);
  return [...byKey.values()];
})();

/** When the generated data was last pulled, if ever. */
export const POLLS_GENERATED_AT: string | null = generated.generatedAt ?? null;

/** Most recent poll end date across a race, for sorting. */
export function latestPollDate(race: RacePolls): string {
  return race.polls.reduce((max, p) => (p.endDate > max ? p.endDate : max), "");
}

/** Simple average margin (first candidate minus second) across a race's polls. */
export function averageMargin(race: RacePolls): number | null {
  if (race.polls.length === 0 || race.candidates.length < 2) return null;
  const [a, b] = race.candidates;
  const diffs = race.polls
    .map((poll) => {
      const pa = poll.results.find((r) => r.candidate === a.name)?.pct;
      const pb = poll.results.find((r) => r.candidate === b.name)?.pct;
      return pa != null && pb != null ? pa - pb : null;
    })
    .filter((d): d is number => d != null);
  if (diffs.length === 0) return null;
  return diffs.reduce((s, d) => s + d, 0) / diffs.length;
}
